components/common/payment-icons:
{{#with theme_settings}}
    {{#or show_accept_amex show_accept_discover show_accept_mastercard show_accept_paypal show_accept_visa show_accept_sage show_accept_wallet show_accept_sage}}
        <div class="footer-payment-image">
            {{#if show_accept_visa}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-1.png" alt="payment-1">
            {{/if}}
            {{#if show_accept_mastercard}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-2.png" alt="payment-2">
            {{/if}}
            {{#if show_accept_amex}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-3.png" alt="payment-3">
            {{/if}}
            {{#if show_accept_discover}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-4.png" alt="payment-4">
            {{/if}}
            {{#if show_accept_paypal}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-5.png" alt="payment-5">
            {{/if}}
            {{#if show_accept_sage}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-6.png" alt="payment-6">
            {{/if}}
            {{#if show_accept_wallet}}
                <img class="lazyload" src="{{cdn 'img/loading.svg'}}" data-src="/product_images/uploaded_images/payment-7.png" alt="payment-7">
            {{/if}}
        </div>
    {{/or}}
{{/with}}

components/common/social-links:
{{#if social_media}}
    <ul class="socialLinks socialLinks--alt">
        {{#each social_media}}
            <li class="socialLinks-item">
                {{#if display_name '===' 'twitter'}}
                    <a class="icon icon--google" href="https://www.tiktok.com/@fabspeed?lang=en" target="_blank" rel="noopener">
                        <img src="https://store-fh9wsjv2.mybigcommerce.com/content/tik-tok.svg"></img>
                    </a>
                {{else}}
                    <a class="icon icon--{{display_name}}" href="{{url}}" target="_blank" rel="noopener">
                        <svg><use xlink:href="#icon-{{display_name}}" /></svg>
                    </a>
                {{/if}}
            </li>
        {{/each}}
    </ul>
{{/if}}

pages/page:
{{#partial "page"}}
<div class="themevale_breadcrumb">
    {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
    {{#unless theme_settings.hide_page_heading }}
        <h1 class="page-heading">{{ page.title }}</h1>
    {{/unless}}
</div>
<main class="page">
    {{#if page.sub_pages}}
    <!--<nav class="navBar navBar--sub">-->
    <!--    <ul class="navBar-section account-navigation">-->
    <!--    {{#each page.sub_pages}}-->
    <!--        <li class="navBar-item"><a class="navBar-action" href="{{url}}">{{title}}</a></li>-->
    <!--    {{/each}}-->
    <!--    </ul>-->
    <!--</nav>-->
    {{/if}}
    
    
    <div class="page-content">
        
        {{{region name="page_builder_content"}}}
        {{#replace '%%Syndicate%%' page.content}}
            {{> components/page/rss_feed}}
        {{else}}
            <p>{{{page.content}}}</p>
        {{/replace}}
        
    </div>
    {{#if page.feed}}
        <ul>
            {{#each page.feed}}
                <li>
                    <h6><a href="{{url}}" target="_blank">{{title}}</a></h6>
                    <p>{{content}}</p>
                </li>
            {{/each}}
        </ul>
    {{/if}}
</main>

{{/partial}}

{{> layout/base}}
